import{_ as t,o,c as n,a2 as a}from"./chunks/framework.DGk0zlJw.js";const g=JSON.parse('{"title":"Beacon Componentization Refactor · State Flow and Component Contract Freeze (Phase 0 closing delivery)","description":"","frontmatter":{},"headers":[],"relativePath":"design/redesign-2026-10-16-契约.md","filePath":"design/redesign-2026-10-16-契约.md"}'),i={name:"design/redesign-2026-10-16-契约.md"};function s(d,e,r,c,l,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="beacon-componentization-refactor-·-state-flow-and-component-contract-freeze-phase-0-closing-delivery" tabindex="-1">Beacon Componentization Refactor · State Flow and Component Contract Freeze (Phase 0 closing delivery) <a class="header-anchor" href="#beacon-componentization-refactor-·-state-flow-and-component-contract-freeze-phase-0-closing-delivery" aria-label="Permalink to &quot;Beacon Componentization Refactor · State Flow and Component Contract Freeze (Phase 0 closing delivery)&quot;">​</a></h1><p><strong>Basis</strong>: <code>docs/design/redesign-plan-2026-10-16.md</code> (external design draft) + <code>docs/design/redesign-2026-10-16-核验.md</code> (50-item current-state verification, <code>759742b</code>) + <code>docs/design/redesign-2026-10-16-映射与迁移.md</code> (§6 pending-decision list, <code>e1229fc</code>). <strong>Time point</strong>: 2026-10-16. The PATROL1016 inspection ticket authorized 「可自主决策的直接拍板并写进仓内决策记录」 — this file is that decision record; irreversible or out-of-scope matters remain open questions (see §4). <strong>Nature</strong>: the state flow contract and the component contract are frozen as of this document; later phases (Phase 2-6) build without touching the public surface of this contract, and changing the contract requires a new decision entry.</p><hr><h2 id="_1-four-concepts-state-event-command-operation-result" tabindex="-1">1. Four concepts (State / Event / Command / Operation Result) <a class="header-anchor" href="#_1-four-concepts-state-event-command-operation-result" aria-label="Permalink to &quot;1. Four concepts (State / Event / Command / Operation Result)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>In-repo location</th><th>Semantics</th></tr></thead><tbody><tr><td><strong>State</strong></td><td><code>WidgetState</code> (12-field characterization in Mapping &amp; Migration §2.1) + <code>IStateStore</code> (snapshot surface)</td><td>Normalized projection of external-system facts + derived state (IsStale/ConnectionHealthy); the single authoritative snapshot lives in the State Store</td></tr><tr><td><strong>Event</strong></td><td><code>Events/Events.cs</code> six records: <code>WidgetStateChanged</code> <code>ConnectionHealthChanged</code> <code>WidgetsInvalidated</code> <code>AggregateStatusChanged</code> <code>NotificationRaised</code> <code>ActionExecuted</code></td><td>The state stream&#39;s transport surface; subscribe and unsubscribe via <code>IEventBus.Subscribe/Publish</code> (the UI side marshals back to the UI thread via <code>SubscribeOnUi</code>, RFC §11)</td></tr><tr><td><strong>Command</strong></td><td><code>ActionConfig.Type</code> (7 Type strings) → <code>ActionRunner</code> → <code>IActionExecutor</code></td><td>The single entry point for user intent; the targeted refresh after execution goes through <code>RefreshScheduler.Kick</code> (state flows back after an Action); no separate command bus is introduced</td></tr><tr><td><strong>Operation Result</strong></td><td><code>ActionResult(ActionId, Success, Message, OutputPath, CompletedAt)</code> (<code>Models/ActionModels.cs:28</code>)</td><td>Current two states (bool Success); the target five states are in §4 已代决③</td></tr></tbody></table><h2 id="_2-state-flow-contract-frozen" tabindex="-1">2. State flow contract (frozen) <a class="header-anchor" href="#_2-state-flow-contract-frozen" aria-label="Permalink to &quot;2. State flow contract (frozen)&quot;">​</a></h2><ol><li><strong>Publish point</strong>: the success path and the stale path of <code>WidgetHost</code> both publish uniformly via <code>IStateStore.Update</code> (since <code>f5d1d91</code>); the <code>WidgetStateChanged</code> event shape is unchanged and the UI notices nothing.</li><li><strong>IStateStore signature</strong> (<code>Abstractions/IStateStore.cs</code>, frozen as landed in <code>f5d1d91</code>): <code>Update(WidgetState)</code> / <code>Get(widgetId)</code> / <code>Snapshot()</code> / <code>Invalidate(widgetIds)</code>.</li><li><strong>Change detection rule</strong> (<code>Services/StateStore.cs</code> content key): all fields except <code>FetchedAt</code> participate (length-prefixed segments guard against delimiter ambiguity; Payload is sorted by key, insertion-order independent); an <code>IsStale</code> / <code>ConnectionHealthy</code> flip always publishes (scenario F5: the offline-degradation event must not be swallowed by dedup, anchored by <code>StateStoreTests.DedupOn_StaleFlip_Republishes</code>).</li><li><strong>Dedup enabled by default</strong> (<code>d71bdc8</code>, 已代决②): a refresh-time-only change does not trigger downstream; the snapshot still keeps the latest <code>FetchedAt</code>.</li><li><strong>Invalidation</strong>: consumers of <code>WidgetsInvalidated</code> are responsible for dropping local residue; <code>Invalidate</code> is the matching Store-side cleanup surface (App-side wiring of the shared Store is handled together with the Phase 3 binding engine; the current UI goes through the event bus and is unaffected).</li></ol><h2 id="_3-component-contract-frozen-the-four-compatibility-items-adopted-as-in-mapping-migration-§5" tabindex="-1">3. Component contract (frozen; the four compatibility items adopted as in Mapping &amp; Migration §5) <a class="header-anchor" href="#_3-component-contract-frozen-the-four-compatibility-items-adopted-as-in-mapping-migration-§5" aria-label="Permalink to &quot;3. Component contract (frozen; the four compatibility items adopted as in Mapping &amp; Migration §5)&quot;">​</a></h2><ol><li>The six JSON file names and existing field semantics are unchanged (config / connections / widgets / pins / actions / notifications).</li><li>The new component model enters as incremental optional fields on <code>WidgetConfig</code>; old files stay readable; no migration, no renaming. <code>ConfigVersion</code> only increments when migration semantics are actually needed — pure additive optional fields write no keys, so it stays untouched (⑤⑧⑨ each have unit test anchors); zero noise for existing config.</li><li>The existing 23 widget type keys, 7 Action Type strings, and all window layers (L0-L3 + Settings) are preserved; componentization only replaces the rendering segment and the state entry point.</li><li>The 71-item on-machine acceptance checklist and the CI visual-evidence scenarios remain in force; the phase counts as complete only after the full Phase 6 regression.</li><li>Component descriptor shape and mounting surface (已代决⑤, <code>src/Beacon.Core/Models/ComponentDescriptor.cs</code>): <code>ComponentDescriptor(Id, Type, Props, Children)</code> → <code>WidgetConfig.Components: Dictionary&lt;string, ComponentDescriptor&gt;?</code> (open set of surface keys, current vocabulary tile / row / detail); nested composition is allowed with blast-proof caps (8 levels / 32 children / 256 nodes); structurally invalid = discard the whole tree back to traditional rendering + diagnostics, no silent pruning.</li><li>Bindings and instances (已代决⑥, <code>src/Beacon.Core/Models/ComponentBinding.cs</code> + <code>Services/WidgetInstanceResolver.cs</code>): bindings enter the tree with their node (<code>ComponentBinding(Field, Source)</code>); sources have three kinds: state / selector / const; an instance = the surface-key resolution result, fail-closed (no surface tree / invalid tree → null → traditional rendering); instances and config are shared read-only, resolution does no IO.</li><li>Binding engine (已代决⑦, <code>src/Beacon.Core/Services/ComponentBindingEngine.cs</code>): every bound node in the tree keys its Field value out as <code>{node path}.{field}</code> (same convention as the validation diagnostics); the source-name map reserves key <code>&quot;&quot;</code> = own state; any binding that cannot resolve a value returns an empty string (fail-closed) — no throwing, no guessing; selector sources hook up only Core&#39;s existing pure-function selectors.</li><li>Data source aggregation (已代决⑧, <code>WidgetConfig.Sources: Dictionary&lt;string, Dictionary&lt;string,string&gt;&gt;?</code> surface key → source name → widgetId): source names match exactly and case-sensitively; the reserved key <code>&quot;&quot;</code> (the instance&#39;s own state) must not be used; ≤16 sources per surface; an illegal declaration discards the whole surface (all extra sources dropped, own state always available) + diagnostics into the load log; the runtime source map is built by <code>WidgetInstanceResolver.ResolveSources</code> from the state snapshot via widgetId lookup, sources that cannot be found are simply absent (the binding side returns an empty string); composition aggregates multiple WidgetIds at the component layer, and the <code>WidgetState</code> single-<code>ConnectionId</code> Provider convention is untouched.</li><li>Shared consumption (已代决⑨, <code>src/Beacon.Core/Services/ComponentSourceIndex.cs</code>): one and the same state object can be consumed by any number of instances (resolution is a pure function, shared by reference, not copied); <code>ConsumedWidgetIds(instance)</code> gives the full set of widgetIds an instance needs (own Id first, extra sources in declaration order, duplicate widgetIds deduped), and <code>SourcesOf(instances)</code> reverse-maps widgetId → consuming instance set; the index is rebuilt on demand and never cached.</li><li>Component-layer pure-function boundary (已代决⑩): <code>ComponentTreeValidator</code> / <code>ComponentSourcesValidator</code> / <code>WidgetInstanceResolver</code> / <code>ComponentBindingEngine</code> / <code>ComponentSourceIndex</code> are all static classes (no instance state, no cache surface); no public method takes runtime services (Provider / executors / Store / event bus / Clock, etc.) — state and config enter only as data parameters; the number of state lookups is decided solely by the source declarations and is independent of layout shape, and the engine does zero lookups during resolution. Changing layout = re-resolving against the same state snapshot, producing no data requests (doubly anchored by the construction and tests of Phase 3 row 6).</li></ol><h2 id="_4-decision-record" tabindex="-1">4. Decision record <a class="header-anchor" href="#_4-decision-record" aria-label="Permalink to &quot;4. Decision record&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Decision</th><th>Basis and rollback</th><th>Status</th></tr></thead><tbody><tr><td>已代决①</td><td><code>IStateStore</code> contract frozen = the signature as landed in <code>f5d1d91</code></td><td>Landed + 15 unit tests; revertible in a single commit</td><td>In effect</td></tr><tr><td>已代决②</td><td><code>FetchedAt</code> removed from content equality; <code>suppressUnchanged</code> defaults to true (<code>d71bdc8</code>)</td><td>Explicit in the design draft §4.1; always-publish on stale/health flip is anchored by unit tests; &quot;Last update&quot; only shows in the stale state (RFC §6.2.6), so dedup in the fresh state loses no visible timestamp; the rollback switch is kept (pass false via the constructor), single-commit rollback</td><td>In effect</td></tr><tr><td>已代决③</td><td>Target five states for <code>ActionResult</code> (Succeeded / Failed / Cancelled / TimedOut / Unsupported, additionally distinguishing 「请求已接受」 from 「最终完成」), to evolve when the Phase 5 feedback system lands; the current two states stay for compatibility</td><td>The five states are contract evolution, not breakage: new members enter additively and executors map them one by one; changing early would just idle (no Cancel/Timeout execution surface today)</td><td>Decided, pending implementation (Phase 5)</td></tr><tr><td>已代决④</td><td>The four compatibility items of Mapping &amp; Migration §5 are frozen as-is (this file §3)</td><td>All are conservative unchanged surfaces; changes require a new decision entry</td><td>In effect</td></tr><tr><td>已代决⑤</td><td>Component descriptor shape: <code>ComponentDescriptor(Id?, Type, Props:string→string, Children[])</code> mounted at <code>WidgetConfig.Components: Dictionary&lt;string,ComponentDescriptor&gt;?</code> (open set of surface keys, current tile/row/detail vocabulary); <strong>nested composition is allowed</strong>, with blast-proof caps of 8 levels / 32 children / 256 nodes; structurally invalid discards the whole tree back to traditional rendering + diagnostics</td><td>The user authorized deciding the descriptor shape on 2026-10-16 (FW1016D). §3.2 already framed &quot;incremental optional fields&quot;; this item fixes only the shape: ① an open set of surface keys rather than a single root — the same widget takes different forms at L0 tile / L2 row / L3 detail, and a single-root tree would force all three layers into one shape; ② Props are all strings — same convention as <code>WidgetConfig.Config</code>/<code>ActionConfig.Parameters</code>, hand-written JSON cannot produce type ambiguity, and type conversion stays at render time; ③ allowing nesting is the very reason descriptors exist (Surface.Card wraps Text, StatusCard wraps indicator + title; as-built §2 already composes this way), but unbounded nesting would amplify one hand-typo into a recursive stack overflow — hence the caps and whole-tree discard when invalid (no silent pruning into half a tree, no crash of the resident process); ④ the registry of component type keys and the unknown-key policy are left to Phase 3 row 3 binding dispatch (the registry lives on the render side and is not preset here); ⑤ no migration semantics, so <code>ConfigVersion</code> stays untouched (optional fields write no keys, existing widgets.json is readable with zero noise, anchored by unit tests)</td><td>In effect</td></tr><tr><td>已代决⑥</td><td>Binding declarations enter the tree with their node (<code>ComponentBinding(Field, Source)</code> mounted at <code>ComponentDescriptor.Bindings</code>); binding sources have three kinds <code>state</code>/<code>selector</code>/<code>const</code> (the state path is closed over the supported field set + <code>payload:key</code>); extra data sources go through <code>SourceName</code> (mapping in ⑧); instance resolution is fail-closed (no surface tree / invalid tree → null → traditional rendering); instances and config are shared read-only</td><td>The user authorized deciding the descriptor shape on 2026-10-16 (FW1016D); this item is the descriptor&#39;s binding surface. ① Entering the tree with the node rather than a widget-level binding table — a binding table would need its own node locators, i.e. describing the tree twice; ② the three source kinds cover all value-fetch scenarios (own state field / derived selector / static literal); a free-path DSL would make the error surface of hand-written JSON unbounded; ③ validation moves up front to load and resolution time — runtime never guesses bad paths (unknown kind and bad paths error out at resolution time and go into the diagnostics log); ④ instances do not copy the tree or Config, sharing read-only (same convention as the <code>WidgetConfig.Config</code> dictionary); changing layout only re-resolves, no IO</td><td>In effect</td></tr><tr><td>已代决⑦</td><td>Binding engine = pure functions <code>ComponentBindingEngine.Resolve(WidgetInstance, WidgetState)</code> / <code>Resolve(WidgetInstance, IReadOnlyDictionary&lt;string,WidgetState&gt;)</code>; bound values in the tree key out as <code>{node path}.{field}</code>; the source-name map reserves key <code>&quot;&quot;</code> = own state (the primary state), and extra source names are built from ⑧&#39;s instance data source declarations; any unresolvable value returns an empty string; the selector source registry admits only Core&#39;s existing pure functions (<code>value-hint</code> = <code>WidgetValueHint.Of</code>, <code>quota-windows</code> = <code>WidgetValueHint.MultiWindow</code>)</td><td>The user authorized deciding on 2026-10-16 (FW1016D); this item is the runtime executor of the descriptor&#39;s binding surface. ① Pure function, no IO, no Provider dependency is the constructive guarantee of the Phase 3 row 6 invariant — state is passed in by the caller as a snapshot, so changing layout only re-resolves and triggers no requests; ② path keys share one convention with the validation diagnostics (id or <code>child{index}</code>, joined by <code>/</code>), so the rendering segment and the diagnostics log can point at the same node — no second locator scheme; ③ unresolvable values return an empty string rather than throwing — in a resident process one bad hand-written JSON value must not blow up the whole panel; a missing value manifests as an empty string (row 3 validation already reports bad paths into the diagnostics at load/resolution time; runtime is only the last line of defense); ④ the selector registry admits no user-writable entries — new selectors go through Core code plus a registry entry, avoiding an arbitrary callable surface inside JSON</td><td>In effect</td></tr><tr><td>已代决⑧</td><td>Multi-source composition: surface-level declaration <code>WidgetConfig.Sources</code> (surface key → source name → widgetId) as incremental optional fields; the runtime map is built by <code>WidgetInstanceResolver.ResolveSources(instance, stateOf)</code> from the state snapshot via widgetId lookup (unfindable sources are absent, the binding side returns an empty string); source names match exactly and case-sensitively; the reserved key <code>&quot;&quot;</code> = the instance&#39;s own state and must not be used by extra declarations; ≤16 sources per surface; an illegal declaration discards the whole surface (all extra sources dropped, own state always available) + diagnostics into the load log</td><td>The user authorized deciding on 2026-10-16 (FW1016D). Mapping &amp; Migration §3.3 already framed &quot;composition happens at the component layer aggregating multiple WidgetIds, and the <code>WidgetState</code> single-<code>ConnectionId</code> Provider convention is not broken&quot;; this item lands the implementation surface: ① the declaration sits at surface level, not node level — data source aggregation is an instance property, at the same level as <code>Components</code> under the same surface-key convention, not attached again on tree nodes (nodes only write a <code>SourceName</code> reference); ② the reserved key <code>&quot;&quot;</code> carries own state and extra sources are named explicitly — the instance Id already is the self, and addressing it directly by widgetId would be redundant and unreadable in JSON (&quot;runs&quot;/&quot;quota&quot; are easier to write than a widgetId); ③ exact source-name matching, no case folding — source names are identifiers the user hard-writes; silently tolerating case is harder to debug than erroring; ④ an illegal declaration drops only that surface&#39;s extra sources, not the instance: extra sources are an additive capability and own state is always available; knocking the whole surface back to traditional rendering over one bad declaration is excessive punishment (only structural invalidity of the component tree discards the whole tree — the tree is the rendering skeleton, sources are not); ⑤ the 16-sources-per-surface cap belongs to the same hand-written JSON blast-radius family as Components&#39; 8/32/256; ⑥ it does not move with <code>ConfigVersion</code> (optional fields write no keys, existing widgets.json is readable with zero migration, anchored by unit tests)</td><td>In effect</td></tr><tr><td>已代决⑨</td><td>Different components share one and the same state: resolution is a pure function that reads state read-only, shared by reference, not copied; <code>ComponentSourceIndex.ConsumedWidgetIds(instance)</code> = the full set of widgetIds an instance needs (own Id first, extra sources in declaration order, duplicate widgetIds deduped), <code>ComponentSourceIndex.SourcesOf(instances)</code> reverse-maps widgetId → consuming instance set; the index is a pure function, rebuilt on demand, never cached</td><td>The user authorized deciding on 2026-10-16 (FW1016D). Design-draft acceptance 3 「同一份数据可以被不同类型的组件展示」 + acceptance 7 「数据变化只更新必要的消费者」; this item lands the reverse-queryable fact surface: ① shared by reference, not cloned — when one state is consumed by N surfaces there is only one copy in memory; the content equality of <code>WidgetState</code> (the dedup/event convention) only means something when state is shared; ② the index is needed in both directions — 「这份状态被谁消费」 is the routing surface for invalidation and updates (row 6), and 「这个组件要哪些源」 is the scoping surface for subscription and refresh (⑧&#39;s source declarations); both derive from the same Sources declaration, so two conflicting conventions cannot arise; ③ own Id always enters the consumption set — when a binding&#39;s SourceName is empty it reads own state, and missing the registration would drop the self consumer from 「这份状态变了」; ④ the index is not cached — where to put a cache and when to invalidate it is exactly the source of 「无意义请求」 (what row 6 tackles head-on)</td><td>In effect</td></tr><tr><td>已代决⑩</td><td>Component-layer pure-function boundary (Phase 3 row 6): the five component-layer types (<code>ComponentTreeValidator</code> / <code>ComponentSourcesValidator</code> / <code>WidgetInstanceResolver</code> / <code>ComponentBindingEngine</code> / <code>ComponentSourceIndex</code>) are all static classes, and no public method takes runtime services (<code>IConnectionProvider</code> / <code>IActionExecutor</code> / <code>IStateStore</code> / <code>IConfigurationStore</code> / <code>ICacheStore</code> / <code>ISecretStore</code> / <code>IEventBus</code> / <code>IClock</code> / <code>INotificationSink</code>); state lookups = 1 for self + the number of Sources declarations, independent of layout shape; zero lookups once the engine holds the map</td><td>The user authorized deciding on 2026-10-16 (FW1016D). Row 6 is a 「保证」 not a 「功能」; this item turns it into a regression-testable boundary: ① reflection guards the public signatures — the moment someone stuffs a Provider or Store into the component layer for 「顺手取数」, changing layout would quietly fire data requests and the test goes red immediately, caught earlier than review or comments; ② the lookup count guards behavior — from a 1-node layout to 200 levels of nesting, the state lookup count stays unchanged (2 = self + 1 extra source) and the engine does zero lookups during resolution, directly proving 「布局不驱动数据请求」; ③ static classes = no cache surface, so the question of 「什么时候失效」 cannot even arise — ⑨ already fixed the index as rebuilt on demand and never cached; this item generalizes that constraint to the whole component layer (where to put a cache and when to invalidate it is exactly the source of 「无意义请求」)</td><td>In effect</td></tr><tr><td><strong>留问</strong></td><td>The boundary between HTML small screens and <code>master-plan.md:769</code> 「不引入 WebView」 (Mapping &amp; Migration §6.3)</td><td><strong>Ruled (2026-10-17 user order &quot;proceed with this design&quot;)</strong>: controlled HTML/CSS subset + native rendering, no JS, no WebView2 (full decision: docs/design/phase4-html-ruling-2026-10-17.en.md)</td><td>Closed</td></tr></tbody></table><h2 id="_5-outstanding-items" tabindex="-1">5. Outstanding items <a class="header-anchor" href="#_5-outstanding-items" aria-label="Permalink to &quot;5. Outstanding items&quot;">​</a></h2><ul><li><code>BeaconRuntime</code> creates the shared <code>StateStore</code> and injects it into <code>WidgetHost</code>/the future binding engine (App-side wiring, Phase 3); for now the <code>WidgetHost</code> internal default Store is what takes effect.</li><li><code>Events.cs</code> event count: Mapping &amp; Migration §1.6 originally recorded 「5 个事件记录」 when the actual count is 6 (including <code>ActionExecuted</code>); corrected alongside this file.</li></ul><h2 id="_6-capability-boundary-three-tiers-p0-01-2026-10-17" tabindex="-1">6. Capability boundary, three tiers (P0-01, 2026-10-17) <a class="header-anchor" href="#_6-capability-boundary-three-tiers-p0-01-2026-10-17" aria-label="Permalink to &quot;6. Capability boundary, three tiers (P0-01, 2026-10-17)&quot;">​</a></h2><p>The component contract says 「what can be written」; actual support is labeled in three tiers, per surface (<code>tile</code> / <code>row</code> / <code>detail</code>) below — do not mistake 「the contract allows it」 for 「it is accepted」; acceptance follows the on-machine checklist (§3.4&#39;s 71 items + the Phase 6 full regression):</p><table tabindex="0"><thead><tr><th>Tier</th><th>Scope</th><th>tile</th><th>row</th><th>detail</th></tr></thead><tbody><tr><td>Core model available</td><td><code>ComponentDescriptor</code> / tree validation / source validation / <code>WidgetInstanceResolver</code> / <code>ComponentBindingEngine</code> / <code>ComponentSourceIndex</code> (static pure functions, anchored by Core unit tests)</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>App wired</td><td>Declarative rendering + binding reads + extra-source routing (PinTile / FloatingTile / QuickPanel rows / DetailWindow) + missing-source display</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Real user scenario accepted</td><td>71-item on-machine checklist + Phase 6 regression + sample runtime acceptance (<code>docs/samples/declarative-vertical-sample.md</code> &quot;What to verify&quot;)</td><td>⏳</td><td>⏳</td><td>⏳</td></tr></tbody></table><p>Convention note: saving a component tree only persists to disk + re-registers (P3-02 split), fetching no data and publishing no re-render event — a surface renders with the new tree on the <strong>next state arrival</strong>; when no content change is suppressed by dedup, reopening the surface shows it. The settings-page save copy no longer claims 「正在重渲染」.</p>',17)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
